import * as api from './api.js';
import {statuses,dateKey,normalizePhone,csv} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let orders=[];let page=1,view='orders',selected=new Set(),activeId=null,toastTimer,listMode='all';const PAGE=10;
const time=d=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(d));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
async function reloadOrders(){orders=await api.loadOrders();render();}
function filtered(){const q=$('#search').value.trim().toLowerCase();return orders.filter(o=>(listMode==='all'||(listMode==='pending'?['new','contacted'].includes(o.status):o.status==='completed'))&&(!q||[o.name,o.phone,o.id,normalizePhone(o.phone)].some(v=>v.toLowerCase().includes(q))||(/[0-9]/.test(q)&&normalizePhone(o.phone).includes(normalizePhone(q))))&&(!$('#status').value||o.status===$('#status').value)&&(!$('#source').value||o.source===$('#source').value)&&(!$('#ad-id').value.trim()||String(o.adId||'').toLowerCase().includes($('#ad-id').value.trim().toLowerCase()))&&($('#duplicate').value!=='yes'||o.matches.length>0)&&($('#duplicate').value!=='no'||!o.matches.length)&&(!$('#from').value||dateKey(o.createdAt)>=$('#from').value)&&(!$('#to').value||dateKey(o.createdAt)<=$('#to').value)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
function render(){const all=filtered();page=Math.max(1,Math.min(page,Math.ceil(all.length/PAGE)||1));const rows=all.slice((page-1)*PAGE,page*PAGE);const today=orders.filter(o=>dateKey(o.createdAt)===dateKey(Date.now())).length;const dup=orders.filter(o=>o.matches.length).length;$('#nav-total').textContent=orders.length;$('#stats').innerHTML=[['今日订单',today,'今日收到的全部订单','▤'],['待联系',orders.filter(o=>o.status==='new').length,'及时联系，把握每次机会','◷'],['首次提交',orders.length-dup,'独立客户首次下单','↗'],['已确认',orders.filter(o=>o.status==='confirmed').length,'已确认的客户订单','✓'],['已完成',orders.filter(o=>o.status==='completed').length,'订单跟进已完成','✓']].map((s,i)=>`<div class="stat ${i===3?'stat-dup':''}"><span class="stat-label">${s[0]}</span><span class="stat-symbol">${s[3]}</span><b>${String(s[1]).padStart(2,'0')}</b><small>${s[2]}</small></div>`).join('');$('#result-count').textContent=all.length;$('#rows').innerHTML=rows.map(o=>`<article class="order-row" data-order="${esc(o.id)}"><input class="order-check" type="checkbox" data-select="${esc(o.id)}" aria-label="选择 ${esc(o.id)}" ${selected.has(o.id)?'checked':''}><div class="order-summary"><div class="order-title"><span class="short-id">${esc(o.id)}</span><button class="customer" data-detail="${esc(o.id)}">${esc(o.name)}</button><span class="badge ${o.matches.length?'dup':'fresh'}" title="${esc([...new Set(o.matches.map(m=>m.reason))].join(' / '))}">${o.matches.length?'重粉':'新客户'}</span><span class="source-chip">${esc(o.source)}</span><span class="ad-chip">广告 ID：${esc(o.adId||'未记录')}</span></div><div class="order-meta"><span>电话 <strong class="mono">${esc(o.phone)}</strong></span><span>${esc(o.product)} × ${o.quantity}</span><span>金额 <strong>NT$ ${o.price.toLocaleString()}</strong></span><span class="status ${esc(o.status)}">${statuses[o.status]}${o.status==='invalid'&&o.invalidReason?' · '+esc(o.invalidReason):''}</span></div><div class="order-date">${dateKey(o.createdAt)} ${time(o.createdAt)}${o.notes?`<span class="note-preview">备注：${esc(o.notes)}</span>`:''}</div></div><div class="row-actions"><div class="status-actions">${['contacted','confirmed','shipped','completed'].map(st=>`<button data-status="${st}" data-id="${esc(o.id)}" class="quick-status ${o.status===st?'is-current':''}" aria-pressed="${o.status===st}">${statuses[st]}</button>`).join('')}<select class="invalid-reason" data-reason="${esc(o.id)}" aria-label="${esc(o.id)} 无效原因"><option value="">无效原因</option>${['重粉','电话错误','无法联系','无购买意愿','其他'].map(r=>`<option ${o.invalidReason===r?'selected':''}>${r}</option>`).join('')}</select><button data-invalid="${esc(o.id)}" class="quick-status ${o.status==='invalid'?'is-current invalid-active':''}">无效</button></div><div class="utility-actions"><select class="other-status" data-other-status="${esc(o.id)}" aria-label="${esc(o.id)} 其他状态"><option value="">其他状态</option><option value="new">待联系</option><option value="cancelled">已取消</option></select><button class="copy-order" data-copy="${esc(o.id)}">一键复制</button><button class="detail-button" data-detail="${esc(o.id)}">详情</button></div></div></article>`).join('');$('#empty').hidden=!!all.length;$('#empty b').textContent=orders.length?'没有符合条件的订单':'暂无订单';$('#empty p').textContent=orders.length?'试着调整搜索内容或清除筛选。':'客户提交订单后将显示在这里。';$('#empty-clear').hidden=!orders.length;$('#page-label').textContent=`共 ${all.length} 笔${all.length?` · 显示 ${(page-1)*PAGE+1}–${Math.min(page*PAGE,all.length)} 笔`:''}`;$('#page-number').textContent=`${page} / ${Math.ceil(all.length/PAGE)||1}`;$('#prev').disabled=page===1;$('#next').disabled=page*PAGE>=all.length;$('#selected-label').textContent=selected.size?`已选择 ${selected.size} 笔 · 导出选择订单`:'未勾选时，导出目前筛选结果';$('#select-page').checked=!!rows.length&&rows.every(o=>selected.has(o.id));$('#select-page').indeterminate=rows.some(o=>selected.has(o.id))&&!$('#select-page').checked;}
function clear(){for(const id of ['search','ad-id','status','duplicate','source','from','to'])$('#'+id).value='';document.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('chosen',b.dataset.days==='all'));page=1;listMode='all';document.querySelectorAll('[data-list]').forEach(b=>b.classList.toggle('active',b.dataset.list==='all'));selected.clear();render();}
function openDetail(id){const o=orders.find(o=>o.id===id);if(!o)return;activeId=id;$('#detail-body').innerHTML=`<div class="dialog-heading"><div><p class="eyebrow">订单信息</p><h2>订单详情</h2></div><button class="icon-button" data-close="detail" aria-label="关闭详情">×</button></div><div class="detail-identity"><span class="avatar">${esc(o.name.slice(0,1))}</span><div><h2>${esc(o.name)}</h2><p>${esc(o.id)}</p></div></div><span class="badge ${o.matches.length?'dup':'fresh'}">${o.matches.length?'重粉订单':'首次提交'}</span><dl><dt>手机号码</dt><dd>${esc(o.phone)} <button class="detail-button" id="copy-phone">复制</button></dd><dt>下单时间</dt><dd>${dateKey(o.createdAt)} ${time(o.createdAt)}</dd><dt>商品</dt><dd>${esc(o.product)} × ${o.quantity}</dd><dt>订单金额</dt><dd>NT$ ${o.price.toLocaleString()}</dd><dt>来源</dt><dd>${esc(o.source)}</dd><dt>广告来源 ID</dt><dd>${esc(o.adId||'未记录')}</dd><dt>下单 IP</dt><dd class="mono">${esc(o.ip||'未记录')}</dd><dt>下单设备</dt><dd>${esc(o.device||'未记录')}</dd></dl><dl></dl><div class="detail-section"><h3>重粉比对 ${o.matches.length?`· ${o.matches.length} 笔历史纪录`:''}</h3>${o.matches.length?o.matches.map(m=>{const p=orders.find(x=>x.id===m.id);return `<div class="match-item"><button data-detail="${esc(m.id)}">${esc(m.id)} ↗</button> · ${esc(m.reason)}重复<p>${esc(p?.name)} · ${p?dateKey(p.createdAt)+' '+time(p.createdAt):''}</p></div>`;}).join(''):'<p class="muted">提交时没有相同姓名或电话的历史订单。</p>'}</div><form id="detail-form"><div class="detail-section"><h3>跟进管理</h3><label for="detail-status">订单状态</label><select id="detail-status" aria-label="订单状态">${Object.entries(statuses).map(([v,l])=>`<option value="${v}" ${v===o.status?'selected':''}>${l}</option>`).join('')}</select><label for="notes">跟进备注</label><textarea id="notes" maxlength="2000" placeholder="记录联系结果、约定时间或人工复核说明…">${esc(o.notes)}</textarea><button class="primary full">保存更改</button></div></form><div class="detail-section"><h3>操作纪录</h3>${o.logs.length?o.logs.slice().reverse().map(l=>`<div class="log">${esc(l.text)}<br>${dateKey(l.at)} ${time(l.at)}</div>`).join(''):'<p class="muted">尚无跟进修改纪录。</p>'}</div>`;if(!$('#detail').open)$('#detail').showModal();$('#detail-form').onsubmit=async e=>{e.preventDefault();const next=$('#detail-status').value,note=$('#notes').value;try{if(o.status!==next||o.notes!==note){if(next==='invalid'&&!o.invalidReason){toast('请先在订单列表选择无效原因');return;}await api.saveOrder(id,next,note,o.invalidReason||'');await reloadOrders();openDetail(id);}toast('更改已保存');}catch(error){toast(error.message);}};$('#copy-phone').onclick=async()=>{try{await navigator.clipboard.writeText(o.phone);toast('电话已复制');}catch{toast('无法存取剪贴板，请手动选择电话复制。');}};}
$('#today').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'long'}).format(Date.now());Object.entries(statuses).forEach(([v,l])=>$('#status').add(new Option(l,v)));
document.addEventListener('click',e=>{const statusButton=e.target.closest('[data-status]');if(statusButton)updateStatus(statusButton.dataset.id,statusButton.dataset.status);const invalid=e.target.closest('[data-invalid]');if(invalid){const reason=invalid.closest('.order-row').querySelector('[data-reason]').value;if(!reason){toast('请先选择无效原因');return;}updateStatus(invalid.dataset.invalid,'invalid',reason);}const copy=e.target.closest('[data-copy]');if(copy){const o=orders.find(x=>x.id===copy.dataset.copy);copyText(`姓名：${o.name}\n电话：${o.phone}\n商品：${o.product} × ${o.quantity}\n来源：${o.source}\n广告 ID：${o.adId||'未记录'}`);}const tab=e.target.closest('[data-list]');if(tab){listMode=tab.dataset.list;page=1;selected.clear();document.querySelectorAll('[data-list]').forEach(b=>b.classList.toggle('active',b===tab));render();}const close=e.target.closest('[data-close]');if(close)$('#'+close.dataset.close).close();const detail=e.target.closest('[data-detail]');if(detail)openDetail(detail.dataset.detail);const nav=e.target.closest('[data-view]');if(nav){view=nav.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===nav));$('#orders-view').hidden=view==='settings';$('#settings-view').hidden=view!=='settings';$('#crumb').textContent=view==='settings'?'系统设置':'全部订单';$('#page-title').textContent='订单工作台';$('#list-title').firstChild.textContent='全部订单 ';clear();}const quick=e.target.closest('[data-days]');if(quick){const d=quick.dataset.days;const now=new Date();const end=dateKey(now);let start=end;if(d!=='all'){now.setDate(now.getDate()-(d==='1'?1:d==='7'?6:0));start=dateKey(now);}$('#from').value=d==='all'?'':start;$('#to').value=d==='all'?'':d==='1'?start:end;document.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('chosen',b===quick));page=1;selected.clear();render();}});
for(const id of ['search','ad-id','status','duplicate','source','from','to'])$('#'+id).addEventListener(['search','ad-id'].includes(id)?'input':'change',()=>{page=1;selected.clear();if(['from','to'].includes(id))document.querySelectorAll('[data-days]').forEach(b=>b.classList.remove('chosen'));render();});
$('#rows').onchange=e=>{if(e.target.dataset.otherStatus&&e.target.value){updateStatus(e.target.dataset.otherStatus,e.target.value);return;}const id=e.target.dataset.select;if(id){e.target.checked?selected.add(id):selected.delete(id);render();}};$('#select-page').onchange=e=>{filtered().slice((page-1)*PAGE,page*PAGE).forEach(o=>e.target.checked?selected.add(o.id):selected.delete(o.id));render();};$('#prev').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};$('#clear').onclick=clear;$('#empty-clear').onclick=clear;$('#refresh').onclick=async()=>{try{await reloadOrders();toast('订单已刷新');}catch(e){toast(e.message);}};$('#export').onclick=()=>{const rows=selected.size?orders.filter(o=>selected.has(o.id)):filtered();if(!rows.length){toast('目前没有可导出的订单');return;}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv(rows)],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=`NK-orders-${dateKey(Date.now())}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`已导出 ${rows.length} 笔订单`);};render();



let savingOrder=false;
async function updateStatus(id,status,reason=''){if(savingOrder)return;const o=orders.find(x=>x.id===id);if(!o||!statuses[status])return;if(o.status===status&&(o.invalidReason||'')===reason){toast('当前已是此状态');return;}savingOrder=true;try{await api.saveOrder(id,status,o.notes,reason);await reloadOrders();toast('已保存：'+statuses[status]);}catch(e){toast(e.message);}finally{savingOrder=false;}}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('客户信息已复制');}catch{toast('复制未成功，请在详情中手动复制。');}}

let pixelSettings={facebook:[],tiktok:[]};
function renderPixels(){for(const platform of ['facebook','tiktok']){$('#'+platform+'-pixels').innerHTML=pixelSettings[platform].length?pixelSettings[platform].map((p,i)=>`<div class="pixel-row"><div class="pixel-fields"><label>像素 ID<input data-pixel-platform="${platform}" data-pixel-index="${i}" aria-label="${platform==='facebook'?'FB':'TK'} 像素 ID ${i+1}" placeholder="${platform==='facebook'?'输入数字像素 ID':'输入 TikTok 像素 ID'}" value="${esc(p.id)}" maxlength="100" autocomplete="off"></label></div><label class="pixel-toggle"><input type="checkbox" data-pixel-toggle="${platform}" data-pixel-index="${i}" ${p.enabled?'checked':''}>启用</label><button data-delete-pixel="${platform}" data-pixel-index="${i}" class="delete-pixel" aria-label="删除 ${platform==='facebook'?'FB':'TK'} 像素 ${i+1}">删除</button></div>`).join(''):'<div class="pixel-empty">暂无像素<div>点击「添加」填写像素 ID</div></div>';}}
function settingsChanged(){$('#settings-feedback').textContent='有未保存的修改';$('#settings-feedback').classList.remove('error');}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-pixel]');if(add){const platform=add.dataset.addPixel;pixelSettings[platform].push({id:'',enabled:true});renderPixels();settingsChanged();$('#'+platform+'-pixels input[data-pixel-platform]:last-of-type')?.focus();}const del=e.target.closest('[data-delete-pixel]');if(del){pixelSettings[del.dataset.deletePixel].splice(Number(del.dataset.pixelIndex),1);renderPixels();settingsChanged();}});
document.addEventListener('input',e=>{if(e.target.dataset.pixelPlatform){pixelSettings[e.target.dataset.pixelPlatform][Number(e.target.dataset.pixelIndex)].id=e.target.value;settingsChanged();}});
document.addEventListener('change',e=>{if(e.target.dataset.pixelToggle){pixelSettings[e.target.dataset.pixelToggle][Number(e.target.dataset.pixelIndex)].enabled=e.target.checked;settingsChanged();}});
$('#save-settings').onclick=async()=>{for(const platform of ['facebook','tiktok']){const seen=new Set();for(const p of pixelSettings[platform]){const id=p.id.trim();const label=platform==='facebook'?'FB':'TikTok';if(!id||!(platform==='facebook'?/^\d+$/:/^[A-Za-z0-9]+$/).test(id)){$('#settings-feedback').textContent=`请填写有效的 ${label} 像素 ID（${platform==='facebook'?'仅数字':'字母或数字'}），或删除空白配置。`;$('#settings-feedback').classList.add('error');return;}if(seen.has(id)){$('#settings-feedback').textContent=`${label} 像素 ID 重复，请检查。`;$('#settings-feedback').classList.add('error');return;}seen.add(id);}}const saved=Object.fromEntries(['facebook','tiktok'].map(platform=>[platform,pixelSettings[platform].map(p=>({...p,id:p.id.trim()}))]));try{await api.saveSettings(saved);pixelSettings=saved;renderPixels();$('#settings-feedback').textContent='已保存 · 客户下次打开页面时生效';$('#settings-feedback').classList.remove('error');toast('像素设置已保存');}catch{$('#settings-feedback').textContent='保存失败，请检查网络或重新登录。';$('#settings-feedback').classList.add('error');}};
renderPixels();if(pixelSettings.facebook.length||pixelSettings.tiktok.length)$('#settings-feedback').textContent='已加载像素配置';

async function enterAdmin(){pixelSettings=await api.loadSettings();await reloadOrders();renderPixels();document.body.classList.remove('locked');$('#auth-panel').hidden=true;}
$('#login-form').onsubmit=async e=>{e.preventDefault();$('#send-login').disabled=true;try{await api.sendLogin($('#login-email').value.trim());$('#login-message').textContent='登录邮件已发送，请打开邮件中的登录链接；若邮件提供验证码，也可在下方输入。';}catch(error){$('#login-message').textContent=error.message;}finally{$('#send-login').disabled=false;}};
$('#verify-form').onsubmit=async e=>{e.preventDefault();$('#verify-login').disabled=true;try{await api.verifyLogin($('#login-email').value.trim(),$('#login-token').value.trim());if(await api.restoreLogin())await enterAdmin();}catch(error){$('#login-message').textContent=error.message;}finally{$('#verify-login').disabled=false;}};
$('#logout').onclick=async()=>{await api.signOut();location.reload();};
(async()=>{if(!api.configured()){$('#login-message').textContent='后台已部署，数据库正在初始化，完成后即可登录。';$('#send-login').disabled=true;$('#verify-login').disabled=true;return;}try{if(await api.restoreLogin())await enterAdmin();else $('#login-message').textContent='仅授权管理员可访问客户资料。';}catch(error){$('#login-message').textContent=error.message;}})();
